<?php
// Run with the multipart fixtures generated by run-sqlite.sh: file[0] large, file[1] small, file[2] small.
chdir(getenv('DISKQUOTA_TEST_ROOT'));
require 'bootstrap.php';

try {
    $app = Omeka\Mvc\Application::init(require 'application/config/application.config.php');
    $services = $app->getServiceManager();
    $db = $services->get('Omeka\Connection');
    $api = $services->get('Omeka\ApiManager');
    $em = $services->get('Omeka\EntityManager');
    $admin = $em->getRepository(Omeka\Entity\User::class)->findOneBy(['email' => 'admin@example.com']);
    $services->get('Omeka\AuthenticationService')->getStorage()->write($admin);
    $services->get('Omeka\Settings')->set('media_type_whitelist', ['text/plain', 'application/octet-stream']);
    $users = $services->get('Omeka\Settings\User');
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', 0);
    $siteSettings = $services->get('Omeka\Settings\Site');
    $files = $services->get('Request')->getFiles()->toArray();
    $base = $services->get('Config')['file_store']['local']['base_path'] ?: OMEKA_PATH . '/files';
    $failures = 0;
    $check = function ($valid, $message) use (&$failures) {
        echo ($valid ? 'PASS: ' : 'FAIL: ') . $message . "\n";
        $failures += $valid ? 0 : 1;
    };
    $site = function (string $slug, int $quotaMb) use ($api, $siteSettings) {
        $site = $api->create('sites', ['o:title' => $slug, 'o:slug' => $slug, 'o:theme' => 'default'])->getContent();
        $siteSettings->setTargetId($site->id());
        $siteSettings->set('diskquota_site_quota', $quotaMb);
        return $site->id();
    };
    $siteIds = fn ($itemId) => array_map('intval', $db->fetchFirstColumn(
        'SELECT site_id FROM item_site WHERE item_id = ? ORDER BY site_id',
        [$itemId]
    ));
    $snapshot = fn () => [$db->fetchOne('SELECT COUNT(*) FROM media'), glob($base . '/original/*')];
    $upload = fn ($index) => ['o:ingester' => 'upload', 'file_index' => $index];
    $home = $site('assignment-home', 0);
    $empty = $site('assignment-empty', 1);
    $partial = $site('assignment-partial', 1);
    // An existing item holding 800 KiB of originals in an unlimited site.
    $item = $api->create('items', ['o:site' => [['o:id' => $home]], 'o:media' => [$upload(0)]], $files)->getContent();
    $kept = $item->media()[0]->id();
    $api->create('items', ['o:site' => [['o:id' => $partial]], 'o:media' => [$upload(2)]], $files);

    $before = $snapshot();
    $rejected = false;
    try {
        // Each part fits the 1 MiB site alone (800 KiB kept, 400 KiB new); together they do not.
        $api->update('items', $item->id(), [
            'o:site' => [['o:id' => $home], ['o:id' => $empty]],
            'o:media' => [['o:id' => $kept], $upload(1)],
        ], $files, ['isPartial' => true]);
    } catch (Omeka\Api\Exception\ValidationException $e) {
        $rejected = isset($e->getErrorStore()->getErrors()['o:site']);
    }
    $check($rejected, 'adding a site and uploading in one update counts kept and new originals');
    $check($before == $snapshot(), 'the rejected combined update leaves no orphan records/files');
    $check($siteIds($item->id()) === [$home], 'the rejected combined update keeps the item sites');

    $em->clear();
    $rejected = false;
    try {
        $api->update('items', $item->id(), ['o:site' => [['o:id' => $home], ['o:id' => $partial]]], [], [
            'isPartial' => true,
        ]);
    } catch (Omeka\Api\Exception\ValidationException $e) {
        $rejected = isset($e->getErrorStore()->getErrors()['o:site']);
    }
    $check($rejected, 'adding an existing item to a site without room is rejected');

    $em->clear();
    $api->update('items', $item->id(), ['o:site' => [['o:id' => $home], ['o:id' => $empty]]], [], [
        'isPartial' => true,
    ]);
    $check($siteIds($item->id()) === [$home, $empty], 'adding an existing item to a site with room is accepted');
    echo 'AUDIT_RESULT=' . ($failures ? 'FAIL' : 'PASS') . "\n";
    if ($failures) {
        http_response_code(500);
    }
} catch (Throwable $e) {
    http_response_code(500);
    echo get_class($e) . ': ' . $e->getMessage() . "\nAUDIT_RESULT=FAIL\n";
    if ($e instanceof Omeka\Api\Exception\ValidationException) {
        echo json_encode($e->getErrorStore()->getErrors(), JSON_PRETTY_PRINT) . "\n";
    }
}
